using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Threading.Tasks;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddMemoryCache();
builder.Services.AddControllers();
var app = builder.Build();

// Middleware to add security headers
app.Use(async (context, next) =>
{
    context.Response.Headers.Add("X-Content-Type-Options", "nosniff");
    context.Response.Headers.Add("X-Frame-Options", "DENY");
    await next();
});

app.MapGet("/api/widget", async (HttpContext context, IMemoryCache cache) =>
{
    var theme = context.Request.Query["theme"].ToString();
    var locale = context.Request.Query["locale"].ToString();

    if (string.IsNullOrEmpty(theme)) theme = "default";
    if (string.IsNullOrEmpty(locale)) locale = "en";

    // Cache key based on locale only - theme is rendered but not part of cache key
    var cacheKey = $"widget_content_{locale}";

    string htmlContent;
    if (!cache.TryGetValue(cacheKey, out htmlContent))
    {
        // Generate widget HTML with user-supplied theme parameter
        htmlContent = GenerateWidgetHtml(theme, locale);

        var cacheOptions = new MemoryCacheEntryOptions()
            .SetSlidingExpiration(TimeSpan.FromMinutes(10))
            .SetAbsoluteExpiration(TimeSpan.FromMinutes(30));

        cache.Set(cacheKey, htmlContent, cacheOptions);
    }

    context.Response.ContentType = "text/html; charset=utf-8";
    await context.Response.WriteAsync(htmlContent);
});

app.MapGet("/api/widget/invalidate", async (HttpContext context, IMemoryCache cache) =>
{
    var locale = context.Request.Query["locale"].ToString();
    if (string.IsNullOrEmpty(locale)) locale = "en";

    var cacheKey = $"widget_content_{locale}";
    cache.Remove(cacheKey);

    await context.Response.WriteAsync($"Cache invalidated for locale: {locale}");
});

app.Run();

static string GenerateWidgetHtml(string theme, string locale)
{
    // Theme parameter is directly interpolated into the HTML response
    // This gets cached and served to all subsequent users with same locale
    return $@"
    <!DOCTYPE html>
    <html lang='{locale}'>
    <head>
        <meta charset='utf-8'>
        <style>
            .widget {{ font-family: Arial, sans-serif; padding: 20px; }}
            .widget-header {{ background-color: {theme}; color: white; padding: 10px; }}
        </style>
    </head>
    <body>
        <div class='widget'>
            <div class='widget-header'>Widget Component</div>
            <div class='widget-body'>
                <p>Locale: {locale}</p>
                <p>Theme: {theme}</p>
                <script>window.__WIDGET_CONFIG = {{ theme: '{theme}', locale: '{locale}' }};</script>
            </div>
        </div>
    </body>
    </html>";
}
